time-seconds.code:
#include <stdio.h>
struct Time { int hours, minutes, seconds; };
static long by_value(struct Time t) {
    return 3600L * t.hours + 60L * t.minutes + t.seconds;
}
static long by_pointer(struct Time *t) {
    return 3600L * t->hours + 60L * t->minutes + t->seconds;
}
int main(void) {
    struct Time t;
    if (scanf("%d%d%d", &t.hours, &t.minutes, &t.seconds) != 3 ||
        t.hours < 0 || t.hours > 100000 ||
        t.minutes < 0 || t.minutes > 59 ||
        t.seconds < 0 || t.seconds > 59) return 1;
    printf("By value: %ld\n", by_value(t));
    printf("By pointer: %ld\n", by_pointer(&t));
    return 0;
}

display-file.code:
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int main(void) {
    char name[256];
    if (fgets(name, sizeof name, stdin) == NULL) return EXIT_FAILURE;
    name[strcspn(name, "\r\n")] = '\0';
    FILE *fp = fopen(name, "r");
    if (fp == NULL) {
        perror(name);
        return EXIT_FAILURE;
    }
    int ch;
    while ((ch = fgetc(fp)) != EOF) {
        if (putchar(ch) == EOF) {
            fclose(fp);
            return EXIT_FAILURE;
        }
    }
    int failed = ferror(fp);
    if (fclose(fp) == EOF) failed = 1;
    return failed ? EXIT_FAILURE : EXIT_SUCCESS;
}

